-- The two checklists published on 2026-10-17: The Day You Fly Somewhere
-- (Travel) and Making Room for Something You Enjoy (Play).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-17`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-day-you-fly-somewhere', 'The Day You Fly Somewhere', 'For the day you fly when flying is the part you dread. It gets the documents, food and distractions settled early, gives you something to do with your body in the air, and tells the crew you could use an eye kept on you.', 'Travel', '["Put the documents in one pocket the night before — hunting for a boarding pass is its own small crisis.", "Eat something before you leave for the airport — hunger and nerves feel almost identical from the inside.", "Pick an aisle seat if you get to choose — being able to stand up matters more than the view.", "Download enough to fill the whole flight — a signal you cannot count on is one worry removed.", "Tell the cabin crew you are a nervous flyer — they hear it every day and they will check on you.", "Breathe out longer than you breathe in on taxi — a long exhale is what slows a racing heart.", "Learn which noises come when — the gear and the flaps are loud and completely routine.", "Keep water and gum with you, not overhead — what helps is no use shut in the locker.", "Plan the first hour after you land — somewhere to be next gives the flight an end point."]'::jsonb, 'as needed', array['Anxiety', 'Stress']::text[], 1, '2026-10-17T16:00:00+00:00'::timestamptz),
  ('making-room-for-something-you-enjoy', 'Making Room for Something You Enjoy', 'For the weeks that are all obligation and nothing you do for its own sake. It helps you name something you used to enjoy, give it a slot and a low bar, and keep it from turning into one more thing to be good at.', 'Play', '["Name one thing you used to lose hours in — the answer is usually from before you got busy.", "Book twenty minutes for it this week — a hobby with no slot stays a nice idea.", "Get the thing out of its case or box — the setting up is the part that quietly stops you.", "Let the first go be bad on purpose — rusty is the cost of starting again, not a verdict.", "Keep it off the internet this week — an audience turns a pastime into a performance.", "Do not tie it to getting better at it — enjoying it is the whole point and a complete result.", "Say out loud which evening it is happening — a plan spoken survives a busy week better.", "Notice how you feel in the hour afterward — that is the argument for doing it again."]'::jsonb, 'weekly', array['Self-Care', 'Motivation']::text[], 1, '2026-10-17T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
